cat >> test/strings.test.js <<'EOF'

test('slugify lowercases and hyphenates', () => assert.strictEqual(slugify('Hello World'), 'hello-world'));
test('slugify strips Vietnamese diacritics', () => assert.strictEqual(slugify('Xin chào Việt Nam'), 'xin-chao-viet-nam'));
test('slugify converts đ and Đ to d', () => assert.strictEqual(slugify('Đường đi'), 'duong-di'));
test('slugify strips other Latin diacritics', () => assert.strictEqual(slugify('Crème Brûlée à la façon'), 'creme-brulee-a-la-facon'));
test('slugify collapses runs of non-alphanumerics', () => assert.strictEqual(slugify('a  --  b!!!c'), 'a-b-c'));
test('slugify trims leading and trailing hyphens', () => assert.strictEqual(slugify('  --Hello, World!--  '), 'hello-world'));
test('slugify returns empty string when nothing is left', () => assert.strictEqual(slugify('!!! ???'), ''));
test('slugify keeps digits', () => assert.strictEqual(slugify('Top 10 of 2024'), 'top-10-of-2024'));
test('slugify caps length at 50', () => assert.strictEqual(slugify('a'.repeat(80)), 'a'.repeat(50)));
test('slugify does not end with a hyphen when cut at 50', () => {
  const slug = slugify('a'.repeat(49) + ' bbbb');
  assert.strictEqual(slug, 'a'.repeat(49));
  assert.ok(slug.length <= 50 && !slug.endsWith('-'));
});
EOF
npm test 2>&1 | tail -20

